import{z as l,x as A,o as n,c as d,q as t,j as r,D as e,d as s,s as B,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"预期管理与沟通","description":"","frontmatter":{"title":"预期管理与沟通","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/expectations-management.md","filePath":"econ/expectations-management.md","lastUpdated":1791063341000}'),p={name:"econ/expectations-management.md"};function m(D,a,c,h,f,u){const o=A("Mermaid");return n(),d("div",null,[a[2]||(a[2]=t('<h1 id="预期管理与沟通" tabindex="-1">预期管理与沟通 <a class="header-anchor" href="#预期管理与沟通" aria-label="Permalink to &quot;预期管理与沟通&quot;">​</a></h1><div class="epigraph"><p>工具利率受零下界或滞后约束时，路径的话与信息的话成为政策；听进去多少取决于更新率与信任。</p><footer>—— Woodford, Central-Bank Communication；Eggertsson and Woodford 对 ZLB 的前瞻指引；Gürkaynak, Sack and Swanson 的公告效应</footer></div><p><a href="/econ/survey-expectations">上一课</a>表明信念可测且常刚性。本课缺口是<strong>政策如何移动信念</strong>：沟通、前瞻指引。不重列 SPF 回归，不把资产负债表工具提前写完（QE 在后单元）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>NK 里长期利率与预期路径进入总需求。ZLB 时当前隔夜利率动不了，承诺未来更久的宽松（Eggertsson–Woodford）是理论工具。实践：声明、点阵图、记者会。Gürkaynak–Sack–Swanson：公告窗内不只当前利率，路径因子也动。缺口是把高频识别课的「意外」当成沟通的产出，接到粘性信息/疏忽：同样的声明，更新者与未更新者分裂。</p><p><span class="marginnote">Eggertsson and Woodford, <em>Brookings</em> 2003。Gürkaynak, Sack and Swanson, <em>IJCB</em> 2005。Blinder 等沟通综述。Campbell, Evans, Fisher, Justiniano 的 Odyssean vs Delphic。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Odyssean：承诺改变未来反应函数。Delphic：揭示对经济的判断（信息效应）。调查与高频一起：若声明后家庭预期不动、市场价格动，疏忽或注意力配置在家庭侧。HANK：沟通若只动资产价格，财富效应走低 MPC；若动失业预期，走高 MPC。学习：体制转换声明要足够久才能进 PLM。</p><p><span class="marginnote">术语翻译：Odyssean 是「我保证自己未来会怎么做」，像奥德修斯把自己绑在桅杆上，先把自己捆住再行动；Delphic 是「我告诉你我怎么看经济」，像德尔斐神谕只发布预言、不绑定行为。前者直接改变央行的反应函数，后者改变公众对经济状态的判断——同一次发布会可能两者都有，但效果渠道不同。</span></p>',9)),(n(),r(i,null,{default:e(()=>[B(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TALK%5B%22%E5%A3%B0%E6%98%8E%20%2F%20%E6%8C%87%E5%BC%95%22%5D%20--%3E%20ODY%5B%22%E6%94%B9%E5%8F%8D%E5%BA%94%E5%87%BD%E6%95%B0%22%5D%0A%20%20TALK%20--%3E%20DEL%5B%22%E6%8F%AD%E7%A4%BA%E5%88%A4%E6%96%AD%22%5D%0A%20%20ODY%20--%3E%20PATH%5B%22%E8%B7%AF%E5%BE%84%E9%A2%84%E6%9C%9F%22%5D%0A%20%20DEL%20--%3E%20INFO%5B%22%E4%BF%A1%E6%81%AF%E6%95%88%E5%BA%94%22%5D%0A%20%20LAM%5B%22%E8%B0%81%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20EFF%5B%22%E8%B0%83%E6%9F%A5%E4%B8%8E%E4%BB%B7%E6%A0%BC%E7%9A%84%E5%88%86%E8%A3%82%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("p",null,"可信度：时间不一致课已说明承诺难。沟通不能替代制度承诺，但能改变信息集。",-1)),a[4]||(a[4]=E("h2",{id:"机制",tabindex:"-1"},[s("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=E("p",null,"机制是移动状态变量「信念」。在完全信息 RE，沟通要么是揭示私人信息，要么是承诺；没有「解释清楚」的独立通道。有粘性信息，重复沟通提高有效 \\(\\lambda\\)。有疏忽，简单、少噪声的规则节省容量。诊断性：生动情景可能过冲。因此沟通设计依赖本单元前几课选哪一套。",-1)),(n(),r(i,null,{default:e(()=>[B(o,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20ZLB%5B%22%E9%9A%94%E5%A4%9C%E5%88%A9%E7%8E%87%E5%B7%B2%E5%88%B0%E9%9B%B6%20%E5%8A%A8%E4%B8%8D%E4%BA%86%22%5D%20--%3E%20PROMISE%5B%22%E6%89%BF%E8%AF%BA%E6%9C%AA%E6%9D%A5%E6%9B%B4%E4%B9%85%E7%BB%B4%E6%8C%81%E4%BD%8E%E5%88%A9%E7%8E%87%22%5D%0A%20%20PROMISE%20--%3E%20PATH%5B%22%E6%9C%AA%E6%9D%A5%E5%88%A9%E7%8E%87%E8%B7%AF%E5%BE%84%E9%A2%84%E6%9C%9F%E4%B8%8B%E9%99%8D%22%5D%0A%20%20PATH%20--%3E%20INF%5B%22%E9%80%9A%E8%83%80%E9%A2%84%E6%9C%9F%E4%B8%8D%E5%86%8D%E4%B8%8B%E6%BB%91%22%5D%0A%20%20INF%20--%3E%20REAL%5B%22%E5%BD%93%E5%89%8D%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%E8%A2%AB%E6%8B%89%E4%BD%8E%22%5D%0A%20%20REAL%20--%3E%20DEMAND%5B%22%E4%BB%8A%E5%A4%A9%E5%B0%B1%E5%80%9F%E9%92%B1%E6%B6%88%E8%B4%B9%E4%B8%8E%E6%8A%95%E8%B5%84%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">数字实例：名义利率已压到 0、而预期通胀是 −1% 时，实际利率约等于 \\(0-(-1\\%)=1\\%\\)，其实仍在紧缩；若把预期通胀拉回 2%，同样零名义利率对应的实际利率变成 \\(-2\\%\\)。ZLB 下「把话说清楚」就是通过预期这条路替央行降息。</span></p><p><span class="marginnote">常见误区：以为声明一出，所有人立刻更新预期。实际更像消息在人群里慢慢传开——每期只有一部分人重新「读报纸」（粘性信息）。所以同一句话要简单、重复、说足够久，相信的人比例才升上去；一天之内的市场反应可能远大于家庭预期的变化。</span></p><p>与财政：财政路径的沟通同样改李嘉图程度；HANK 里「未来税落在谁头上」的信念直接进乘数。</p><p><span class="marginnote">本课不写新闻稿文案技巧。也不把点阵图当成最优合约。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不估计最优词汇表。QE、TLTRO 是数量工具，后课资产负债表。通胀锚定下一课专写长期预期，本课是一般沟通装置。不进外汇微观结构。</p><p>后课默认：沟通分 Odyssean/Delphic；效力被更新率与信任打折。下一课：长期通胀预期如何被钉住或解钉。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>前瞻指引与声明移动路径预期；ZLB 时更重要。</li><li>Odyssean vs Delphic 决定 IRF 符号。</li><li>家庭与市场价格分裂，用本单元的信息摩擦解释。</li><li>出处：Eggertsson and Woodford 2003；</li></ul>',9))])}const T=l(p,[["render",m]]);export{_ as __pageData,T as default};
